INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('RGPD pour une TPE : l''essentiel en 7 étapes', 'rgpd-tpe-essentiel', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Site internet et conformité', 'Fichier clients, formulaire de contact, cookies : dès que vous avez des clients, le RGPD vous concerne. Les 7 étapes pour être en règle, sans y passer vos week-ends.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Le RGPD s''applique à toutes les entreprises qui gardent des informations sur des personnes : fichier clients, prospects, formulaire de contact, salariés.</li> <li>Pour une TPE, l''essentiel tient en sept étapes : savoir ce que l''on collecte, en garder le moins possible, informer, gérer les cookies, fixer des durées, sécuriser, répondre aux demandes.</li> <li>La CNIL propose des modèles gratuits (registre, mentions) qui font gagner beaucoup de temps.</li> </ul> </div> <p>« Le RGPD, c''est pour les grandes entreprises. » C''est une idée répandue, et elle est fausse. Dès que vous avez un fichier clients, un formulaire sur votre site, une liste de prospects ou un salarié, vous traitez des données personnelles et le règlement s''applique.</p> <p>Bonne nouvelle : pour une petite entreprise, se mettre en règle ne demande ni avocat ni logiciel coûteux. Voici les sept étapes à suivre, avec les outils gratuits de la CNIL.</p> <h2>Ce que le RGPD vous demande, en une phrase</h2> <p>Collecter seulement ce dont vous avez besoin, dire aux personnes ce que vous en faites, le protéger, et ne pas le garder indéfiniment. Le reste en découle. La CNIL résume la démarche dans sa page <a href="https://www.cnil.fr/fr/passer-laction/rgpd-les-premieres-etapes" target="_blank" rel="noopener">RGPD : les premières étapes</a>.</p> <h2>Les 7 étapes</h2> <ol class="etapes"> <li><strong>Faire la liste de vos fichiers.</strong> Clients, prospects, fournisseurs, salariés, abonnés à la newsletter, demandes de devis. Pour chacun : pourquoi vous le tenez, quelles informations il contient, qui y a accès. C''est votre <a href="https://www.cnil.fr/fr/RGDP-le-registre-des-activites-de-traitement" target="_blank" rel="noopener">registre des traitements</a> ; la CNIL fournit un modèle simplifié.</li> <li><strong>Trier les données inutiles.</strong> Avez-vous vraiment besoin de la date de naissance d''un client pour un devis ? Moins vous collectez, moins vous avez à protéger. Supprimez les champs superflus de vos formulaires.</li> <li><strong>Informer les personnes.</strong> Sous chaque formulaire, quelques lignes : qui collecte, pourquoi, combien de temps, et comment exercer ses droits. Le détail va dans une page « Politique de confidentialité » sur votre site.</li> <li><strong>Régler les cookies.</strong> Les cookies de mesure d''audience ou de publicité nécessitent l''accord du visiteur, avant d''être déposés. Le bandeau doit permettre de refuser aussi facilement que d''accepter, comme le rappelle la fiche <a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public sur les cookies</a>.</li> <li><strong>Fixer des durées de conservation.</strong> Un prospect qui ne répond plus depuis trois ans n''a plus à être dans votre fichier commercial. Les factures, elles, se conservent dix ans pour des raisons comptables. Notez une durée pour chaque fichier, et faites le ménage une fois par an.</li> <li><strong>Sécuriser.</strong> Un mot de passe différent par outil, la double authentification sur la messagerie et les comptes importants, des sauvegardes, et des accès retirés quand un salarié part.</li> <li><strong>Savoir répondre aux demandes.</strong> Un client peut demander quelles données vous avez sur lui, les faire corriger ou les faire supprimer. Désignez qui s''en occupe ; la réponse doit en principe arriver dans un délai d''un mois.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de mention sous un formulaire de contact, à adapter</p> <p>« Les informations saisies sont utilisées par [nom de l''entreprise] uniquement pour répondre à votre demande et, si vous devenez client, pour le suivi de votre dossier. Elles sont conservées 3 ans après notre dernier échange. Vous pouvez y accéder, les corriger ou demander leur suppression en écrivant à [adresse e-mail]. Plus d''informations dans notre politique de confidentialité. »</p> </div> <h2>Les points sensibles pour une TPE</h2> <table class="table-article"> <thead><tr><th>Situation</th><th>Ce qu''il faut faire</th></tr></thead> <tbody> <tr><td>Newsletter et prospection par e-mail</td><td>Pour des particuliers : accord préalable (sauf clients existants, pour des produits similaires), et lien de désinscription dans chaque envoi</td></tr> <tr><td>Groupe WhatsApp avec des clients</td><td>Préférer les messages individuels ou une liste de diffusion : dans un groupe, chacun voit le numéro des autres</td></tr> <tr><td>Outils d''IA</td><td>Ne pas y coller de données de clients sans savoir où elles vont (voir notre article sur <a href="/blog/chatgpt-tpe-usages">ChatGPT pour une TPE</a>)</td></tr> <tr><td>Prestataires (site, CRM, comptable)</td><td>Vérifier que le contrat prévoit la protection des données</td></tr> <tr><td>Photos de chantier ou de clients</td><td>Demander l''accord avant de publier une photo où une personne ou une adresse est reconnaissable</td></tr> </tbody> </table> <h2>Que risque une petite entreprise ?</h2> <p>La CNIL contrôle aussi les petites structures, souvent après une plainte. Pour les cas simples, elle dispose d''une <a href="https://www.cnil.fr/fr/la-procedure-de-sanction-simplifiee" target="_blank" rel="noopener">procédure de sanction simplifiée</a> : rappel à l''ordre, injonction de se mettre en conformité, ou amende pouvant aller jusqu''à 20 000 € pour une entreprise dont le chiffre d''affaires est inférieur à 50 millions d''euros. Le risque le plus courant reste pourtant ailleurs : la perte de confiance d''un client dont les données ont fuité.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une auto-école à Saint-Louis</p> <p>Elle garde depuis dix ans les photocopies de pièces d''identité de tous ses anciens élèves dans un dossier partagé, accessible à tous les moniteurs. En une après-midi, elle fait son registre avec le modèle de la CNIL, fixe une durée de conservation, supprime les dossiers anciens et limite l''accès aux seules personnes qui en ont besoin.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Les sites que nous créons intègrent les mentions légales, une politique de confidentialité, un bandeau cookies conforme et des formulaires qui ne demandent que l''essentiel. Site vitrine à partir de 990 €, page unique (Landing Essentielle) à 499 €. Nous pouvons aussi vérifier votre site actuel.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Une micro-entreprise doit-elle respecter le RGPD ?</h3> <p>Oui. Le RGPD s''applique quelle que soit la taille de l''entreprise, dès qu''elle traite des données personnelles : clients, prospects, salariés. Pour une micro-entreprise, les obligations restent simples à mettre en œuvre avec les modèles de la CNIL.</p> <h3>Faut-il un bandeau cookies sur son site ?</h3> <p>Oui, si votre site utilise des cookies qui ne sont pas indispensables à son fonctionnement, comme la mesure d''audience non exemptée ou la publicité. Le bandeau doit permettre de refuser aussi simplement que d''accepter, et les cookies ne doivent être déposés qu''après l''accord.</p> <h3>Combien de temps peut-on garder les coordonnées d''un prospect ?</h3> <p>Pour la prospection commerciale, la CNIL recommande en général de ne pas conserver les données d''un prospect plus de trois ans après le dernier contact venant de lui. Au-delà, supprimez-les ou demandez-lui s''il souhaite rester dans votre fichier.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cnil.fr/fr/passer-laction/rgpd-les-premieres-etapes" target="_blank" rel="noopener">CNIL : RGPD, les premières étapes</a>.</li> <li><a href="https://www.cnil.fr/fr/RGDP-le-registre-des-activites-de-traitement" target="_blank" rel="noopener">CNIL : le registre des activités de traitement</a>, avec modèle.</li> <li><a href="https://www.cnil.fr/fr/cookies-et-autres-traceurs" target="_blank" rel="noopener">CNIL : site web, cookies et autres traceurs</a>.</li> <li><a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public Entreprendre : gérer les cookies sur le site d''une entreprise</a>.</li> <li><a href="https://www.cnil.fr/fr/la-procedure-de-sanction-simplifiee" target="_blank" rel="noopener">CNIL : la procédure de sanction simplifiée</a>.</li> </ul> </div>', 'RGPD pour une TPE : l''essentiel en 7 étapes', 'Registre, formulaires, cookies, durées de conservation, sécurité : les 7 étapes pour mettre une petite entreprise en règle avec le RGPD, sans jargon.', 'RGPD TPE, RGPD petite entreprise, registre des traitements, bandeau cookies, mentions RGPD formulaire', '/assets/images/blog/rgpd-tpe-essentiel.webp', '/assets/images/blog/rgpd-tpe-essentiel.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Prise de rendez-vous en ligne : moins d''appels, moins de lapins', 'prise-rendez-vous-en-ligne', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Automatisation', 'Le téléphone sonne pendant que vous êtes avec un client, et le rendez-vous de 14 h ne vient pas. Ce qu''un agenda en ligne bien réglé change, et comment le choisir.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un agenda en ligne laisse vos clients réserver seuls, à toute heure, sur les créneaux que vous avez décidé d''ouvrir.</li> <li>Les rappels automatiques par SMS ou e-mail la veille du rendez-vous limitent les oublis, et un lien d''annulation libère le créneau pour quelqu''un d''autre.</li> <li>Le bon outil se choisit sur quatre critères : synchronisation avec votre agenda, rappels, règles de réservation, et facilité pour le client.</li> </ul> </div> <p>Vous êtes en pleine coupe, en plein soin ou sur un chantier, et le téléphone sonne. Vous ne décrochez pas, le client ne laisse pas de message, et il réserve ailleurs. Plus tard dans la journée, le rendez-vous de 14 h ne vient pas, sans prévenir. Ces deux situations ont la même solution : laisser vos clients réserver eux-mêmes, et leur rappeler leur rendez-vous automatiquement.</p> <p>Voici comment fonctionne la prise de rendez-vous en ligne, ce qu''elle change pour une petite entreprise, et comment la mettre en place sans perdre la main sur votre planning.</p> <h2>Ce que ça change au quotidien</h2> <ul> <li><strong>Moins d''appels à gérer.</strong> Le client voit les créneaux libres et choisit lui-même, le soir ou le week-end, sans vous interrompre.</li> <li><strong>Moins de rendez-vous manqués.</strong> Un rappel la veille, avec un lien pour annuler ou déplacer, évite le créneau perdu sans prévenir.</li> <li><strong>Un planning plus rempli.</strong> Un créneau annulé redevient visible immédiatement et peut être repris par un autre client.</li> <li><strong>Des demandes mieux préparées.</strong> Le formulaire de réservation recueille ce qu''il vous faut : type de prestation, adresse, photos, remarques.</li> </ul> <h2>Qui en profite le plus</h2> <table class="table-article"> <thead><tr><th>Activité</th><th>Ce qui se réserve en ligne</th></tr></thead> <tbody> <tr><td>Coiffure, beauté, bien-être</td><td>Prestations avec durée fixe, choix du praticien</td></tr> <tr><td>Garages, contrôle, lavage</td><td>Créneaux de dépôt du véhicule</td></tr> <tr><td>Artisans du bâtiment</td><td>Visites de chantier pour établir un devis</td></tr> <tr><td>Professions libérales, coachs</td><td>Consultations, premiers rendez-vous, visioconférences</td></tr> <tr><td>Restaurants, activités de loisirs</td><td>Tables, sorties, ateliers, avec nombre de places</td></tr> </tbody> </table> <h2>Les réglages qui font la différence</h2> <ol class="etapes"> <li><strong>Synchroniser avec votre agenda.</strong> L''outil doit lire votre agenda habituel (Google, Outlook, Apple) pour ne jamais proposer un créneau déjà pris, et y écrire chaque réservation.</li> <li><strong>Définir vos règles.</strong> Durée de chaque prestation, temps de trajet ou de préparation entre deux rendez-vous, délai minimum avant une réservation, nombre maximum par jour. C''est vous qui décidez de ce qui est ouvert.</li> <li><strong>Activer les rappels.</strong> Un message de confirmation à la réservation, un rappel la veille, et un lien pour annuler ou déplacer. Le SMS est souvent plus lu que l''e-mail.</li> <li><strong>Prévoir une politique d''annulation.</strong> Indiquez clairement jusqu''à quand on peut annuler. Pour les prestations longues, certains outils permettent de demander un acompte à la réservation.</li> <li><strong>Mettre le lien partout.</strong> Sur votre <a href="/blog/fiche-google-reunion">fiche Google</a>, votre site, votre page Facebook et Instagram, votre signature d''e-mail et votre message d''absence WhatsApp.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de SMS de rappel, à adapter</p> <p>« Bonjour Julie, petit rappel : votre rendez-vous chez [nom] est demain mercredi à 10 h. Pour le déplacer ou l''annuler : [lien]. À demain ! »</p> </div> <h2>Bien choisir son outil</h2> <ul class="checklist"> <li>Il se synchronise dans les deux sens avec l''agenda que vous utilisez déjà.</li> <li>Il envoie des rappels par SMS et par e-mail, avec votre nom d''expéditeur.</li> <li>La réservation se fait en moins d''une minute sur téléphone, sans créer de compte.</li> <li>Vous pouvez bloquer des périodes (congés, alerte cyclonique) en un clic.</li> <li>Les données sont hébergées de façon conforme au RGPD, et vous pouvez les exporter.</li> <li>Le prix reste raisonnable par rapport au nombre de rendez-vous : beaucoup d''outils ont une formule gratuite ou peu chère pour démarrer.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une esthéticienne à Saint-Joseph</p> <p>Elle passait une partie de ses pauses à répondre aux demandes de rendez-vous sur Messenger. Elle ouvre ses créneaux en ligne, ajoute le lien sur sa fiche Google et en réponse automatique sur Messenger, et active un rappel par SMS la veille. Les messages qu''elle reçoit portent désormais surtout sur des questions de soins, plus sur les horaires.</p> </div> <h2>Aller plus loin : la prise de rendez-vous par message</h2> <p>Beaucoup de clients préfèrent écrire plutôt que cliquer sur un lien. Un <a href="/blog/agent-ia-repondre-clients-24h">agent IA</a> peut répondre sur Messenger ou Instagram, poser les questions utiles, proposer un créneau libre et l''inscrire directement dans votre agenda. Il doit se présenter comme un assistant automatique et vous transmettre les demandes particulières.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous mettons en place votre agenda en ligne, les rappels et la synchronisation avec vos outils (automatisation à partir de 490 €). Pour que les rendez-vous se prennent aussi par message, notre agent IA répond sur Messenger et Instagram et remplit votre planning : mise en service de 490 € à 890 €, puis 149 € à 249 €/mois.</p> <p><a href="/agent24-7" class="encadre-lien">Découvrir INES, l''agent IA</a> · <a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a></p> </div> <h2>Questions fréquentes</h2> <h3>Comment réduire les rendez-vous non honorés ?</h3> <p>Envoyez une confirmation à la réservation et un rappel la veille, par SMS de préférence, avec un lien pour annuler ou déplacer facilement. Pour les prestations longues ou coûteuses, une politique d''annulation claire, voire un acompte, responsabilise le client.</p> <h3>Peut-on garder la main sur son planning avec la réservation en ligne ?</h3> <p>Oui. Vous choisissez les jours, les horaires, la durée des prestations, les temps de pause et le délai minimum avant une réservation. Vous pouvez aussi valider chaque rendez-vous manuellement si vous préférez.</p> <h3>Comment ajouter un lien de réservation sur sa fiche Google ?</h3> <p>Depuis votre fiche d''établissement Google, modifiez les informations de l''entreprise et ajoutez l''adresse de votre page de réservation dans le champ prévu pour les liens de rendez-vous. Le bouton apparaît ensuite sur votre fiche dans Google et Google Maps.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/fiche-google-reunion">Fiche Google : apparaître sur Google Maps à La Réunion en 7 étapes</a>.</li> <li><a href="/blog/agent-ia-repondre-clients-24h">Agent IA : répondre à vos clients 24 h/24</a>.</li> <li><a href="https://support.google.com/business/answer/6303076?hl=fr" target="_blank" rel="noopener">Google : définir des horaires exceptionnels</a>, pour bloquer congés et fermetures.</li> <li><a href="https://www.cnil.fr/fr/passer-laction/rgpd-les-premieres-etapes" target="_blank" rel="noopener">CNIL : RGPD, les premières étapes</a>.</li> <li>Offres DIGITA : <a href="/solutions">page Solutions</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Prise de rendez-vous en ligne : le guide pour les TPE', 'Agenda en ligne, rappels par SMS, acompte, synchronisation : comment mettre en place la prise de rendez-vous en ligne et réduire les rendez-vous manqués.', 'prise de rendez-vous en ligne, agenda en ligne TPE, rappel rendez-vous SMS, réservation en ligne Réunion', '/assets/images/blog/prise-rendez-vous-en-ligne.webp', '/assets/images/blog/prise-rendez-vous-en-ligne.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Site internet d''artisan : les 7 pages qui font venir des devis', 'site-internet-artisan', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Un beau site qui ne génère aucun appel ne sert à rien. Les pages qui comptent pour un artisan réunionnais, ce qu''il faut y mettre, et les erreurs qui font fuir.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Le site d''un artisan a un seul objectif : transformer un visiteur qui cherche un professionnel en demande de devis ou en appel.</li> <li>Sept pages suffisent : accueil, services, réalisations, zone d''intervention, avis, à propos, et contact ou devis.</li> <li>Ce qui fait la différence n''est pas le design mais la clarté : ce que vous faites, où, et comment vous joindre, visible en quelques secondes sur un téléphone.</li> </ul> </div> <p>Quand un particulier cherche un carreleur, un électricien ou un menuisier, il compare souvent deux ou trois entreprises en quelques minutes, sur son téléphone. Il regarde les photos de chantiers, vérifie que vous intervenez dans sa commune, lit quelques avis, et appelle celui qui lui inspire confiance et qu''il arrive à joindre.</p> <p>Votre site doit répondre à ces questions avant qu''il les pose. Voici les sept pages qui comptent, et ce qu''il faut mettre dans chacune.</p> <h2>Les 7 pages d''un site d''artisan</h2> <ol class="etapes"> <li><strong>L''accueil.</strong> En haut de page, en une phrase : votre métier et votre zone (« Électricien à Saint-André et dans l''Est »). Juste en dessous, un bouton d''appel et un bouton « Demander un devis ». Puis vos services principaux, trois photos de réalisations et deux ou trois avis.</li> <li><strong>Les services.</strong> Une section ou une page par grand type de travaux : rénovation électrique, dépannage, borne de recharge. Pour chacun : ce qui est inclus, les délais habituels, et des photos. Une page par service vous aide aussi à être trouvé sur Google pour chaque recherche.</li> <li><strong>Les réalisations.</strong> C''est la page la plus regardée. Classez vos chantiers par type, avec des photos avant et après, la commune et une phrase sur la difficulté rencontrée. Demandez l''accord du client avant de publier et évitez de montrer l''adresse exacte.</li> <li><strong>La zone d''intervention.</strong> Les communes où vous vous déplacez, clairement listées. À La Réunion, préciser que vous allez « dans les Hauts » ou non évite beaucoup d''appels inutiles.</li> <li><strong>Les avis.</strong> Reprenez des avis Google récents, avec le prénom et la commune, et un lien vers votre fiche. Notre guide sur les <a href="/blog/avis-google-entreprise">avis Google</a> explique comment en obtenir régulièrement.</li> <li><strong>À propos.</strong> Votre parcours, vos qualifications, vos assurances et labels s''ils existent, une photo de vous ou de l''équipe. Les gens font appel à quelqu''un, pas à un logo.</li> <li><strong>Contact et devis.</strong> Téléphone cliquable, adresse e-mail, horaires, et un formulaire court : type de travaux, commune, délai souhaité, photos. Plus le formulaire est simple, plus il est rempli.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Phrase d''accroche à adapter</p> <p>« Carrelage et faïence à Saint-Pierre et dans le Sud. Devis gratuit sous 48 h, chantiers propres, plus de 10 ans d''expérience. » Le visiteur sait en une ligne ce que vous faites, où, et pourquoi vous choisir.</p> </div> <h2>Les erreurs qui font fuir</h2> <table class="table-article"> <thead><tr><th>Erreur</th><th>Pourquoi c''est un problème</th><th>La solution</th></tr></thead> <tbody> <tr><td>Numéro de téléphone introuvable</td><td>Le visiteur pressé appelle le concurrent</td><td>Bouton d''appel visible en permanence sur mobile</td></tr> <tr><td>Photos de banque d''images</td><td>Elles ne prouvent rien et se repèrent vite</td><td>Vos vrais chantiers, même pris au téléphone</td></tr> <tr><td>Site lent ou illisible sur mobile</td><td>La plupart des visites se font sur téléphone</td><td>Images allégées, texte lisible, test sur votre propre téléphone</td></tr> <tr><td>Dernière réalisation datant de 3 ans</td><td>On se demande si l''entreprise existe encore</td><td>Ajouter un chantier par mois</td></tr> <tr><td>Formulaire de 15 champs</td><td>Personne ne le termine</td><td>4 ou 5 champs, photos facultatives</td></tr> </tbody> </table> <h2>Être trouvé sur Google</h2> <ul class="checklist"> <li>Un titre de page par service et par zone, par exemple « Rénovation de salle de bain à Saint-Denis ».</li> <li>Des textes rédigés avec les mots de vos clients, pas ceux du catalogue fournisseur.</li> <li>Votre site relié à votre <a href="/blog/fiche-google-reunion">fiche Google</a>, avec les mêmes coordonnées partout.</li> <li>Un nom de domaine à votre nom, et pas seulement une sous-adresse d''une plateforme gratuite.</li> <li>Les mentions légales et une politique de confidentialité : elles sont obligatoires, et elles rassurent (voir notre article sur le <a href="/blog/rgpd-tpe-essentiel">RGPD pour une TPE</a>).</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un menuisier aluminium à Saint-Benoît</p> <p>Son ancien site présentait surtout l''histoire de l''entreprise et une galerie de photos sans légende. Il le réorganise en quatre services (fenêtres, baies, portails, garde-corps), ajoute pour chaque chantier la commune et le type de pose, et remplace le long formulaire par cinq questions. Les demandes reçues indiquent désormais le type de travaux et la commune, ce qui lui permet de préparer ses visites.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous créons des sites d''artisans pensés pour les demandes de devis : site vitrine de 5 pages à partir de 990 € (690 € si vous avez déjà un logo), puis 49 €/mois de maintenance sur 12 mois, hébergement compris. Pour démarrer avec une seule page, la Landing Essentielle coûte 499 €, livrée en 5 jours ouvrés.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/outils/audit-seo" class="encadre-lien">Lancer l''audit SEO gratuit de votre site</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien de pages faut-il pour un site d''artisan ?</h3> <p>Cinq à sept pages suffisent pour la plupart des artisans : accueil, services, réalisations, zone d''intervention, avis, à propos et contact. Certaines peuvent être des sections de la page d''accueil si votre activité est simple.</p> <h3>Faut-il afficher ses prix sur son site ?</h3> <p>Ce n''est pas obligatoire pour des travaux sur devis, mais donner des repères aide le client : « à partir de », fourchettes par type de chantier, ou prix des déplacements. Cela filtre aussi les demandes qui ne correspondent pas à votre activité.</p> <h3>Comment obtenir plus de demandes de devis avec son site ?</h3> <p>Rendez le téléphone et le formulaire visibles sur chaque page, montrez des réalisations récentes avec la commune, affichez des avis, et gardez un formulaire court. Reliez aussi le site à votre fiche Google, d''où viennent beaucoup de visites.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/prix-site-internet-reunion">Prix d''un site internet à La Réunion : le vrai coût</a>.</li> <li><a href="/blog/site-vitrine-ou-page-facebook">Site vitrine ou page Facebook : que choisir pour une entreprise à La Réunion ?</a></li> <li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">Google : guide de démarrage en référencement (SEO)</a>.</li> <li><a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public Entreprendre : cookies et site d''entreprise</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Site d''artisan : les 7 pages qui apportent des devis', 'Accueil, services, réalisations, zone d''intervention, avis, devis : les 7 pages d''un site d''artisan qui transforme les visiteurs en demandes de devis.', 'site internet artisan, site artisan Réunion, site vitrine BTP, demande de devis en ligne, page réalisations', '/assets/images/blog/site-internet-artisan.webp', '/assets/images/blog/site-internet-artisan.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Lancer sa boutique en ligne à La Réunion : le guide pratique', 'boutique-en-ligne-reunion', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'E-commerce', 'Une boutique en ligne ne vend pas toute seule. Catalogue, livraison depuis l''île, règles de la vente à distance et premiers visiteurs : le plan pour démarrer du bon pied.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une boutique en ligne est un vrai commerce : catalogue, photos, livraison, paiement, service client et visibilité se préparent avant l''ouverture.</li> <li>Depuis La Réunion, la livraison est le sujet numéro un : retrait en boutique, livraison sur l''île, et envois vers la métropole n''ont ni les mêmes coûts ni les mêmes formalités.</li> <li>La vente à distance impose des règles précises : CGV, mentions légales, droit de rétractation de 14 jours, délai de livraison et médiateur de la consommation.</li> </ul> </div> <p>Beaucoup de commerçants réunionnais vendent déjà en ligne sans boutique : photos sur Facebook, commandes en message, paiement à la livraison. Ça marche, jusqu''au moment où les messages deviennent ingérables et où les clients demandent à commander le soir, en voyant le stock et les prix.</p> <p>Ouvrir une vraie boutique en ligne règle ce problème, à condition de la préparer comme un commerce. Voici les étapes, dans l''ordre.</p> <h2>1. Définir ce que vous vendez, et à qui</h2> <p>Une boutique qui propose tout à tout le monde a du mal à se faire remarquer. Commencez par une gamme courte, que vous maîtrisez, pour une clientèle précise : produits péi, articles de puériculture, matériel de pêche, cosmétiques naturels. Vous élargirez une fois que les premières ventes vous auront appris ce qui part.</p> <h2>2. Choisir la plateforme</h2> <table class="table-article"> <thead><tr><th>Solution</th><th>Points forts</th><th>Points de vigilance</th></tr></thead> <tbody> <tr><td>Plateforme clé en main par abonnement</td><td>Rapide à lancer, hébergement et sécurité gérés</td><td>Abonnement mensuel et parfois commission sur les ventes</td></tr> <tr><td>Solution open source (WooCommerce, PrestaShop…)</td><td>Pas de commission, grande liberté</td><td>Hébergement, mises à jour et sécurité à assurer</td></tr> <tr><td>Boutique sur mesure</td><td>Adaptée exactement à votre façon de vendre</td><td>Budget de départ plus élevé</td></tr> <tr><td>Places de marché</td><td>Visibilité immédiate</td><td>Commissions, peu de contrôle sur la relation client</td></tr> </tbody> </table> <p>Quelle que soit la solution, vérifiez trois points : le paiement par carte sécurisé, la gestion des stocks, et la possibilité de régler la livraison selon la zone.</p> <h2>3. Organiser la livraison depuis l''île</h2> <ul> <li><strong>Retrait sur place ou en point relais local</strong> : simple, gratuit pour le client, et souvent apprécié.</li> <li><strong>Livraison sur l''île</strong> : par vous-même, un coursier ou un transporteur. Fixez des zones et des tarifs clairs ; les Hauts et certains écarts demandent plus de temps.</li> <li><strong>Envois vers la métropole et l''étranger</strong> : coûts plus élevés, délais plus longs, et formalités douanières. La TVA, l''octroi de mer et les déclarations ne fonctionnent pas comme pour une boutique installée en métropole. Faites valider votre organisation par votre expert-comptable ou le <a href="https://www.douane.gouv.fr/" target="_blank" rel="noopener">service des douanes</a> avant d''ouvrir ces destinations.</li> </ul> <p>Affichez les frais et délais de livraison avant le paiement. Des frais découverts à la dernière étape font souvent renoncer le client au dernier moment.</p> <h2>4. Respecter les règles de la vente à distance</h2> <p>La fiche <a href="https://entreprendre.service-public.fr/vosdroits/F23455" target="_blank" rel="noopener">Service Public sur le commerce en ligne</a> détaille les obligations. Les principales :</p> <ul class="checklist"> <li>Des <strong>mentions légales</strong> qui identifient l''entreprise, et des <strong>conditions générales de vente</strong> accessibles avant la commande.</li> <li>Des <strong>prix TTC</strong> et les frais de livraison indiqués clairement.</li> <li>Une <strong>date ou un délai de livraison</strong> ; sans date annoncée, la livraison doit intervenir au plus tard 30 jours après la commande.</li> <li>Le <a href="https://www.service-public.fr/particuliers/vosdroits/F10485" target="_blank" rel="noopener">droit de rétractation</a> de 14 jours pour les particuliers, avec un formulaire type, sauf exceptions (produits personnalisés, denrées périssables…).</li> <li>Un <strong>médiateur de la consommation</strong> désigné, que le client peut saisir gratuitement en cas de litige.</li> <li>Une politique de confidentialité et un bandeau cookies conformes au RGPD (voir notre article sur le <a href="/blog/rgpd-tpe-essentiel">RGPD pour une TPE</a>).</li> </ul> <h2>5. Soigner les fiches produits</h2> <p>Le client ne peut ni toucher ni essayer : la fiche produit fait tout le travail. Pour chacune : plusieurs photos nettes sur fond simple, dont une en situation, un titre clair, une description qui répond aux questions (dimensions, composition, entretien, origine), le prix, le stock et le délai de livraison. Des fiches rédigées avec vos mots aident aussi Google à vous trouver.</p> <h2>6. Faire venir les premiers visiteurs</h2> <p>Une boutique qui vient d''ouvrir ne reçoit presque aucune visite toute seule. Prévoyez le lancement :</p> <ul> <li>prévenir vos clients actuels et vos abonnés Facebook et Instagram ;</li> <li>ajouter le lien de la boutique sur votre fiche Google ;</li> <li>une petite <a href="/blog/budget-publicite-facebook-reunion">campagne publicitaire</a> ciblée sur l''île pendant les premières semaines ;</li> <li>un e-mail automatique pour les paniers abandonnés et un autre pour remercier après l''achat.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une créatrice de bijoux à L''Étang-Salé</p> <p>Elle vendait par messages Instagram et passait ses soirées à envoyer des photos et des prix. Elle ouvre une boutique de trente modèles, avec retrait dans sa commune, livraison sur l''île à tarif unique, et envois en métropole après avoir vérifié les formalités avec son comptable. Ses messages Instagram servent désormais à conseiller, et les commandes se passent sur la boutique.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Notre pack Boutique e-commerce prête à vendre réunit la boutique avec paiement sécurisé et gestion des stocks (2 490 €), les fiches produits rédigées pour le référencement (79 € l''article), le référencement technique (490 €), la campagne de lancement (290 €/mois) et les e-mails automatiques comme le panier abandonné (490 €). Chaque élément peut être pris séparément.</p> <p><a href="/solutions" class="encadre-lien">Voir les packs clés en main</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quelles sont les obligations légales d''un site e-commerce ?</h3> <p>Un site de vente en ligne doit afficher des mentions légales, des conditions générales de vente, des prix TTC avec les frais de livraison, un délai de livraison, et informer du droit de rétractation de 14 jours. Il doit aussi désigner un médiateur de la consommation et respecter le RGPD.</p> <h3>Peut-on vendre en ligne vers la métropole depuis La Réunion ?</h3> <p>Oui, mais les envois entre La Réunion et la métropole sont soumis à des formalités douanières et à des règles fiscales particulières, notamment pour la TVA et l''octroi de mer. Faites valider votre organisation par votre expert-comptable ou les douanes avant d''ouvrir ces livraisons.</p> <h3>Combien coûte une boutique en ligne ?</h3> <p>Cela va d''un abonnement mensuel à une plateforme clé en main jusqu''à plusieurs milliers d''euros pour une boutique sur mesure. Chez DIGITA, une boutique sur mesure démarre à 2 490 €. Prévoyez aussi un budget pour les photos, le lancement et la publicité.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://entreprendre.service-public.fr/vosdroits/F23455" target="_blank" rel="noopener">Service Public Entreprendre : faire du commerce en ligne, règles à respecter</a>.</li> <li><a href="https://www.service-public.fr/particuliers/vosdroits/F10485" target="_blank" rel="noopener">Service Public : achat à distance et droit de rétractation</a>.</li> <li><a href="https://www.douane.gouv.fr/" target="_blank" rel="noopener">Douane française</a> : formalités pour les envois depuis et vers l''outre-mer.</li> <li><a href="https://www.cnil.fr/fr/cookies-et-autres-traceurs" target="_blank" rel="noopener">CNIL : site web, cookies et autres traceurs</a>.</li> <li>Offres DIGITA : <a href="/solutions">page Solutions</a> et <a href="/tarifs">page Tarifs</a>, consultées le 8 novembre 2026.</li> </ul> </div>', 'Boutique en ligne à La Réunion : le guide pour bien démarrer', 'Plateforme, livraison, paiement, obligations légales, trafic : ce qu''il faut préparer pour lancer une boutique en ligne depuis La Réunion, étape par étape.', 'boutique en ligne Réunion, créer site e-commerce, vente en ligne obligations, droit de rétractation, e-commerce 974', '/assets/images/blog/boutique-en-ligne-reunion.webp', '/assets/images/blog/boutique-en-ligne-reunion.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Combien vous coûtent vos tâches répétitives ? Le calcul en 15 minutes', 'temps-perdu-taches-repetitives', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Automatisation', 'Cinq minutes par-ci, dix minutes par-là : à la fin de l''année, ce sont des semaines entières. Une méthode simple pour chiffrer ce temps et choisir quoi automatiser en premier.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une tâche de 10 minutes répétée 5 fois par semaine représente environ 40 heures par an, soit une semaine de travail.</li> <li>Pour savoir quoi automatiser, listez vos tâches répétitives pendant une semaine, chiffrez-les, puis classez-les selon le temps perdu et la facilité d''automatisation.</li> <li>Commencez par la tâche qui coûte le plus et qui suit toujours les mêmes règles : c''est elle qui rapporte le plus vite.</li> </ul> </div> <p>Recopier un formulaire dans un tableur, renvoyer les mêmes informations à chaque demande, relancer un devis, confirmer un rendez-vous, classer une facture : prises une par une, ces tâches ne prennent que quelques minutes. C''est pour cela qu''on ne les remet jamais en question.</p> <p>Additionnées sur une année, elles représentent souvent plusieurs semaines de travail, que vous pourriez passer avec vos clients, sur vos chantiers ou en famille. Voici une méthode simple pour les chiffrer en un quart d''heure, et décider quoi automatiser en premier.</p> <h2>La formule</h2> <p class="formule">Temps perdu par an = durée de la tâche (en minutes) × nombre de fois par semaine × 47 semaines ÷ 60</p> <p>On compte 47 semaines travaillées pour tenir compte des congés et des jours fériés. Pour obtenir un coût, multipliez le nombre d''heures par la valeur d''une heure de votre temps : ce que vous facturez, ou ce que vous coûte un salarié.</p> <h2>Étape 1 : lister vos tâches pendant une semaine</h2> <p>Gardez une feuille ou une note sur votre téléphone. Chaque fois que vous faites quelque chose que vous avez déjà fait à l''identique, notez-le, avec une estimation de la durée. Les candidats habituels :</p> <ul class="checklist"> <li>Recopier les demandes reçues (site, e-mail, Messenger) dans un tableur ou un logiciel.</li> <li>Répondre aux mêmes questions : tarifs, horaires, zone, délais.</li> <li>Prendre, confirmer et rappeler les rendez-vous.</li> <li>Préparer des devis à partir des mêmes éléments.</li> <li>Relancer les devis sans réponse et les factures impayées.</li> <li>Envoyer les factures et les classer pour le comptable.</li> <li>Publier sur les réseaux sociaux.</li> </ul> <h2>Étape 2 : chiffrer</h2> <p>Voici un exemple de calcul pour une petite entreprise de services, avec des durées volontairement modestes :</p> <table class="table-article"> <thead><tr><th>Tâche</th><th>Durée</th><th>Fois par semaine</th><th>Heures par an</th></tr></thead> <tbody> <tr><td>Recopier les demandes de devis</td><td>5 min</td><td>15</td><td>59 h</td></tr> <tr><td>Répondre aux questions courantes</td><td>3 min</td><td>30</td><td>71 h</td></tr> <tr><td>Confirmer et rappeler les rendez-vous</td><td>4 min</td><td>12</td><td>38 h</td></tr> <tr><td>Relancer les devis</td><td>5 min</td><td>8</td><td>31 h</td></tr> <tr><td>Envoyer et classer les factures</td><td>6 min</td><td>10</td><td>47 h</td></tr> <tr><td><strong>Total</strong></td><td></td><td></td><td><strong>246 h, soit près de 7 semaines de 35 h</strong></td></tr> </tbody> </table> <p>Avec une heure valorisée à 40 €, ces cinq tâches représentent près de 10&nbsp;000&nbsp;€ de temps par an. Votre propre total sera différent : c''est justement l''intérêt de faire le calcul avec vos chiffres.</p> <h2>Étape 3 : choisir quoi automatiser d''abord</h2> <p>Pour chaque tâche, posez deux questions : combien de temps elle coûte, et si elle suit toujours les mêmes règles. Placez-la ensuite dans l''une de ces quatre cases :</p> <table class="table-article"> <thead><tr><th></th><th>Règles toujours identiques</th><th>Demande du jugement</th></tr></thead> <tbody> <tr><td><strong>Beaucoup de temps</strong></td><td>À automatiser en premier</td><td>À assister (modèles, IA, avec votre validation)</td></tr> <tr><td><strong>Peu de temps</strong></td><td>À automatiser ensuite, si c''est simple</td><td>À garder telle quelle</td></tr> </tbody> </table> <p>Recopier une demande, envoyer un rappel ou relancer un devis suivent des règles fixes : ce sont des cibles idéales. Chiffrer un chantier complexe ou répondre à une réclamation demandent votre jugement : l''outil peut préparer, mais c''est vous qui validez.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un paysagiste à La Possession</p> <p>En notant ses tâches pendant une semaine, il découvre qu''il passe plus de temps à recopier les demandes et à relancer les devis qu''à préparer les devis eux-mêmes. Il commence par relier son formulaire de site à son tableau de suivi, puis ajoute une <a href="/blog/relances-automatiques-devis-factures">relance automatique</a> des devis. Il garde la main sur le chiffrage, qui demande son œil de professionnel.</p> </div> <h2>Les pièges à éviter</h2> <ul> <li><strong>Automatiser une tâche mal organisée.</strong> Si le processus est confus à la main, il le sera aussi automatisé. Simplifiez d''abord.</li> <li><strong>Tout vouloir faire d''un coup.</strong> Une automatisation à la fois, testée pendant quelques semaines, puis la suivante.</li> <li><strong>Oublier le client.</strong> Un message automatique doit rester chaleureux et personnalisé, et le client doit pouvoir joindre un humain facilement.</li> <li><strong>Ne pas mesurer.</strong> Refaites le calcul trois mois après pour vérifier le temps réellement gagné.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Pendant le diagnostic gratuit de 30 minutes, nous faisons ce calcul avec vous et repérons les deux ou trois automatisations les plus rentables. Nous les mettons ensuite en place : formulaires reliés à votre suivi, relances, rappels de rendez-vous, e-mails automatiques, à partir de 490 €, payés une fois.</p> <p><a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a> · <a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a></p> </div> <h2>Questions fréquentes</h2> <h3>Comment calculer le temps perdu sur une tâche répétitive ?</h3> <p>Multipliez la durée de la tâche en minutes par le nombre de fois où vous la faites chaque semaine, puis par le nombre de semaines travaillées dans l''année, environ 47, et divisez par 60 pour obtenir des heures. Multipliez par la valeur de votre heure pour obtenir un coût.</p> <h3>Quelles tâches automatiser en premier dans une TPE ?</h3> <p>Celles qui prennent le plus de temps et suivent toujours les mêmes règles : recopier les demandes, confirmer les rendez-vous, relancer les devis, envoyer les factures. Les tâches qui demandent votre jugement peuvent être assistées, mais doivent rester validées par vous.</p> <h3>Une automatisation est-elle rentable pour une petite entreprise ?</h3> <p>Elle l''est dès que le temps gagné sur l''année vaut plus que son coût. Une automatisation qui économise deux heures par semaine libère environ 94 heures par an : comparez ce temps, au prix de votre heure, au coût de mise en place.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/automatiser-devis-artisan">Automatiser ses devis : le guide pour les artisans réunionnais</a>.</li> <li><a href="/blog/relances-automatiques-devis-factures">Relances automatiques : ne plus courir après vos devis et factures</a>.</li> <li><a href="/blog/prise-rendez-vous-en-ligne">Prise de rendez-vous en ligne : moins d''appels, moins de lapins</a>.</li> <li><a href="/outils/roi-calculator">Calculateur de ROI marketing DIGITA</a>, pour vos campagnes.</li> <li>Offres DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Tâches répétitives : calculer le temps perdu en 15 minutes', 'Saisies, relances, copier-coller, prises de rendez-vous : la méthode pour chiffrer le temps perdu sur les tâches répétitives et savoir quoi automatiser d''abord.', 'tâches répétitives, temps perdu entreprise, automatiser tâches TPE, rentabilité automatisation, gain de temps', '/assets/images/blog/temps-perdu-taches-repetitives.webp', '/assets/images/blog/temps-perdu-taches-repetitives.webp', 'draft', NOW(), NOW())
